action.code:
if (!head) {
    head = new ListNode(value);
    return true;
}

if (value <= head->val) {
    ListNode* newNode = new ListNode(value);
    newNode->next = head;
    head = newNode;
    return true;
}

ListNode* prev = head;
ListNode* curr = head->next;

while (curr && curr->val < value) {
    prev = curr;
    curr = curr->next;
}

ListNode* newNode = new ListNode(value);
prev->next = newNode;
newNode->next = curr;

return true;

